python3 << 'EOF'
import datasets
import numpy as np
import re
from scipy.optimize import curve_fit
from collections import defaultdict
import warnings
warnings.filterwarnings('ignore')

ds = datasets.load_from_disk('/app/data')

def extract_params(name):
    match = re.search(r'(\d+\.?\d*)([mb])', name.lower())
    if match:
        num = float(match.group(1))
        unit = match.group(2)
        if unit == 'm':
            return num * 1e6
        elif unit == 'b':
            return num * 1e9
    if 'amber' in name.lower():
        return 7e9
    return None

# Prepare data per group
group_data = defaultdict(lambda: {'num_params': [], 'flops': [], 'loss': []})
for row in ds:
    group = row['group']
    params = extract_params(row['model_name'])
    if params:
        group_data[group]['num_params'].append(params)
        group_data[group]['flops'].append(row['flops'])
        group_data[group]['loss'].append(-row['brier_score'])  # loss positive

# Convert to numpy arrays
for group in group_data:
    for key in group_data[group]:
        group_data[group][key] = np.array(group_data[group][key])

# Define candidate models
def model1(x, a, alpha, c):
    num_params, flops = x
    return a * num_params ** (-alpha) + c

def model2(x, a, alpha, beta, c):
    num_params, flops = x
    return a * num_params ** (-alpha) * flops ** (-beta) + c

def model3(x, a, b, alpha, beta, c):
    num_params, flops = x
    return a * num_params ** (-alpha) + b * flops ** (-beta) + c

def model4(x, a, alpha, c):
    num_params, flops = x
    return a * (num_params * flops) ** (-alpha) + c

models = [model1, model2, model3, model4]
names = ['model1', 'model2', 'model3', 'model4']

# For each model, fit per group and compute R²
results = {name: [] for name in names}
coeffs = {name: {} for name in names}

for group, data in group_data.items():
    x = (data['num_params'], data['flops'])
    y = data['loss']
    for model, name in zip(models, names):
        try:
            # Initial guesses
            if name == 'model1':
                p0 = [1.0, 0.1, 0.5]
            elif name == 'model2':
                p0 = [1.0, 0.1, 0.1, 0.5]
            elif name == 'model3':
                p0 = [1.0, 1.0, 0.1, 0.1, 0.5]
            else:
                p0 = [1.0, 0.1, 0.5]
            popt, pcov = curve_fit(model, x, y, p0=p0, maxfev=10000)
            y_pred = model(x, *popt)
            ss_res = np.sum((y - y_pred) ** 2)
            ss_tot = np.sum((y - np.mean(y)) ** 2)
            r2 = 1 - ss_res / ss_tot
            results[name].append(r2)
            coeffs[name][group] = popt
        except Exception as e:
            results[name].append(np.nan)
            coeffs[name][group] = None

# Print average R²
for name in names:
    r2_vals = [r for r in results[name] if not np.isnan(r)]
    if r2_vals:
        print(f'{name}: average R² = {np.mean(r2_vals):.4f}, min R² = {np.min(r2_vals):.4f}')
    else:
        print(f'{name}: no successful fits')

# Print best model per group
print('\nBest model per group (by R²):')
for i, group in enumerate(group_data.keys()):
    best_r2 = -np.inf
    best_name = None
    for name in names:
        r2 = results[name][i]
        if not np.isnan(r2) and r2 > best_r2:
            best_r2 = r2
            best_name = name
    print(f'{group}: {best_name} R²={best_r2:.4f}')
EOF

